public final class UserDtoClass {
    private final Long id;
    private final String name;
    private final String email;

    public UserDtoClass(Long id, String name, String email) {
        this.id = id;
        this.name = name;
        this.email = email;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    // equals, hashCode and toString still need to be written or generated
}

